(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zzc-sj-prepa-ped-j6-idesfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zzc-sj-prepa-ped-j6-idesfm\",\n \"titre\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 54,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n   \"sha256\": \"d5e396c1d74234a08226e617f3246aef66323a11cd976ccc25e72370dd04cb3e\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n     \"slug\": \"prepa-ped-j6-idesfm\",\n     \"pages\": \"\",\n     \"count\": 54,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Pédiatrie\",\n     \"source\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"KJ est âgé de 5 mois et orphelin de mère. Pour préparer son bol de lait infantile de 210 ml, j'utilise :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 4 mesurettes rases de lait\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 5 mesurettes rases de lait\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 6 mesurettes rases de lait\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 7 mesurettes rases de lait\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D. 7 mesurettes rases de lait\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"À 5 mois, KJ reçoit un lait sec en poudre maternisé 1er âge (de la naissance à 5 mois 29 jours), qui se reconstitue à raison d'1 mesurette rase pour 30 ml d'eau bouillie tiédie. 210 ÷ 30 = 7 mesurettes rases. Les autres nombres ne correspondent pas à 210 ml.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Diététique – reconstitution des laits secs ; 2022 Licence Soins aux enfants + Diététique (pptx), diapo 368\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous consultez l'enfant JP âgé de 36 mois. Son Z-score poids pour l'âge est en dessous de moins 3. Cela signifie que JP :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. a un poids normal pour son âge\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. est en surpoids pour son âge\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. est obèse pour son âge\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. a une malnutrition aiguë sévère\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D. a une malnutrition aiguë sévère\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Sur la courbe poids pour l'âge du carnet, un P/A en dessous de la courbe −3 correspond à un « poids gravement insuffisant (MAS) » à référer en urgence. Entre −1 et +1 la croissance est normale ; le surpoids (+2 à +3) et l'obésité (> +3) sont au-dessus de la médiane. Remarque : Le PCIMNE classe la malnutrition aiguë sévère surtout avec le P/T z-score < −3, le PB < 115 mm ou les œdèmes ; le P/A < −3 est le repère du carnet.\\n\\nSource : 2022 Licence Soins aux enfants + Diététique (pptx), diapos 183-184 (courbe P/A)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"PG, sexe masculin, 6 mois, 7 kg, a une diarrhée aiguë et boit avec avidité. Le pli cutané abdominal s'efface lentement et les yeux de PG sont enfoncés. Pour traiter PG, je lui administre durant les 4 premières heures de prise en charge :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 450 ml de SRO\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 350 ml de SRO\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 550 ml de SRO\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 525 ml de SRO\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D. 525 ml de SRO\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Yeux enfoncés, pli cutané qui s'efface lentement, boit avec avidité : signes évidents de déshydratation → plan B. Quantité de SRO pour les 4 premières heures : 75 ml/kg, soit 7 × 75 = 525 ml.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans (2021), p. 24 (Plan B) ; Pediatrie.pdf (cours 1re année commune), Diarrhée – Plan B\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson CB est âgé de 11 mois et pèse 11 kg. Il présente des signes sévères de déshydratation. J'administre durant les 5 heures suivant la 1re heure de traitement :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 770 ml de soluté\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 750 ml de soluté\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 700 ml de soluté\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 650 ml de soluté\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A. 770 ml de soluté\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Signes sévères → plan C : 100 ml/kg de Ringer lactate. Chez le nourrisson de moins de 12 mois : 30 ml/kg en 1 heure, puis 70 ml/kg en 5 heures. 70 × 11 = 770 ml durant les 5 heures qui suivent la 1re heure. Remarque : Pediatrie.pdf propose un autre schéma chez l'enfant de moins de 1 an (30 ml/kg la 1re heure, 40 ml/kg les 2 h suivantes, 30 ml/kg les 3 dernières heures) ; la question suit le schéma PCIMNE.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans (2021), p. 25 (Plan C) ; L'essentiel en pédiatrie tropicale – PédiatrieA-2 (Problèmes fréquents), tableau V\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"DF, garçon, est né à terme eutrophique. La sage-femme vous informe que DF pèse 3420 g au 3e jour de vie et qu'il a perdu 10 % de son poids de naissance. Je déduis que le poids de naissance de DF était de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 3762 g\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 3580 g\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 3800 g\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 3250 g\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 3800 g\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Perte de 10 % : le poids actuel représente 90 % du poids de naissance. PN = 3420 ÷ 0,9 = 3800 g. Cette perte physiologique (environ 1/10 du poids) survient les premiers jours et est récupérée vers J10.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Repères de gain de poids ; Pediatrie.pdf (cours 1re année commune), Modifications des premiers jours\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les sources de difficultés du modèle conceptuel de Virginia Henderson listées ci-après se trouve un intrus. Cochez l'intrus :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Manque de connaissance\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Manque de vision\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Manque de volonté\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Manque de force physique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. Manque de vision\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les sources de difficulté de Virginia Henderson sont le manque de force physique (ne peut pas), le manque de volonté (ne veut pas) et le manque de connaissance (ne sait pas) ; certains auteurs ajoutent l'environnement inadéquat. Le « manque de vision » n'en fait pas partie.\\n\\nSource : L'essentiel en pédiatrie tropicale – PédiatrieA-3 (Raisonnement clinique, annexes), Diagnostic infirmier, p. 331-333\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La bronchiolite aiguë du nourrisson dans sa forme commune non compliquée est provoquée par :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Une bactérie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Un virus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Un parasite\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Un champignon\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. Un virus\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La bronchiolite (IRA basse du nourrisson de 1 mois à 2 ans) est d'origine virale ; le germe à craindre est le virus respiratoire syncytial. Avant 3 ans, les IRA sont surtout virales.\\n\\nSource : Pédiatrie Licence 2 (diaporamas Prof Assé), Infections respiratoires aiguës\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour traiter le nouveau-né présentant une infection bactérienne néonatale tardive, le médecin utilise en priorité l'association :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Ampicilline + aminoside\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Chloramphénicol + aminoside\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Azithromycine + aminoside\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Ceftriaxone + aminoside\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D. Ceftriaxone + aminoside\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'infection tardive (post-natale) est due à des germes hospitaliers (staphylocoques, Klebsiella, Pseudomonas…) souvent résistants à l'ampicilline, qui nécessitent le recours aux céphalosporines de 3e génération, associées à un aminoside. Remarque : Néonatalogie.pdf propose en curatif une trithérapie ampicilline + céfotaxime + gentamicine.\\n\\nSource : L'essentiel en pédiatrie tropicale – PédiatrieA-1 (Le nouveau-né), Infection bactérienne du nouveau-né, p. 78-79 ; Néonatalogie.pdf, XII.1.3\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__8\",\n       \"num\": \"9\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Nourrisson CB, fille, 3 mois, réside à Daloa, présente toux quinteuse, geignement. CB est nourrie au sein uniquement. Fréquence respiratoire 50 cycles/minute, diagnostic du médecin : bronchiolite.\",\n       \"text\": \"CB présente :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 4 données d'indépendance + 5 données de dépendance\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 7 données d'indépendance + 6 données de dépendance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 6 données d'indépendance + 4 données de dépendance\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 5 données d'indépendance + 5 données de dépendance\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 6 données d'indépendance + 4 données de dépendance\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Méthode du cours : les données d'identification (nom, sexe, âge, lieu d'habitation…) et les éléments normaux sont des données d'indépendance ; les signes de la maladie (toux quinteuse, geignement, diagnostic de bronchiolite…) sont des données de dépendance. La correction nationale de la Prépa DE (les J) retient 6 données d'indépendance et 4 de dépendance. Remarque : Le cours donne la méthode mais pas le décompte de ce cas ; le détail des 10 données n'est pas fourni.\\n\\nSource : L'essentiel en pédiatrie tropicale – PédiatrieA-3 (Raisonnement clinique, annexes), Collecte, analyse et interprétation des données, p. 330-331\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__9\",\n       \"num\": \"10\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Nourrisson CB, fille, 3 mois, réside à Daloa, présente toux quinteuse, geignement. CB est nourrie au sein uniquement. Fréquence respiratoire 50 cycles/minute, diagnostic du médecin : bronchiolite.\",\n       \"text\": \"Le diagnostic infirmier est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Perturbation des échanges gazeux reliée à un manque de force physique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Dégagement inefficace des voies respiratoires relié à un manque de force physique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Infection des poumons reliée à un manque de force physique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Détresse respiratoire reliée à un manque de force physique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A. Perturbation des échanges gazeux reliée à un manque de force physique\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Diagnostic infirmier = problème de dépendance + source de difficulté. La bronchiolite atteint la zone d'échange (bronchioles) : le problème est une perturbation des échanges gazeux, et chez un nourrisson de 3 mois la source est le manque de force physique (très jeune âge). « Infection des poumons » et « détresse respiratoire » sont des diagnostics médicaux ; le dégagement inefficace des voies concerne la zone de conduction.\\n\\nSource : Pédiatrie Licence 2 (diaporamas Prof Assé), IRA – implications pour les soins ; L'essentiel en pédiatrie tropicale – PédiatrieA-3 (Raisonnement clinique, annexes), p. 331-332\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__10\",\n       \"num\": \"11\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Nourrisson CB, fille, 3 mois, réside à Daloa, présente toux quinteuse, geignement. CB est nourrie au sein uniquement. Fréquence respiratoire 50 cycles/minute, diagnostic du médecin : bronchiolite.\",\n       \"text\": \"L'objectif de soins est de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Maintenir la fréquence respiratoire dans les limites de la normale (18-30 cycles/min) dans un délai de 1 h après les soins\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Maintenir la fréquence respiratoire dans les limites de la normale (40-60 cycles/min) dans un délai de 1 h après les soins\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Maintenir sa fréquence respiratoire dans les limites de la normale (30-40 cycles/min) dans un délai de 1 h après les soins\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Maintenir sa fréquence respiratoire dans les limites de la normale (60-70 cycles/min) dans un délai de 1 h après les soins\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. Maintenir la fréquence respiratoire dans les limites de la normale (40-60 cycles/min) dans un délai de 1 h après les soins\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient comme objectif une fréquence respiratoire de 40 à 60 cycles/min, valeur normale du nouveau-né et du jeune nourrisson.\\n\\nSource : L'essentiel en pédiatrie tropicale – PédiatrieA-1 (Le nouveau-né), Nouveau-né normal (FR 40-60) ; L'essentiel en pédiatrie tropicale – PédiatrieA-3 (Raisonnement clinique, annexes), Annexes, tableau II\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'enfant qui souffre du kwashiorkor :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. est apathique et grognon\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. aime jouer et jeter les objets\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. réclame à manger et boire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. est constipé mais a l'appétit\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A. est apathique et grognon\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans le kwashiorkor, l'enfant présente une anorexie avec refus de manger et de jouer ; il est hostile, pleurnichard, grognon, apathique et indifférent. À l'inverse, l'enfant marasmique est affamé, actif et a l'appétit conservé.\\n\\nSource : L'essentiel en pédiatrie tropicale – PédiatrieA-2 (Problèmes fréquents), Malnutrition protéino-énergétique, p. 112-114 ; Pédiatrie Licence 2 (diaporamas Prof Assé), Malnutrition\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'infection bactérienne précoce du nouveau-né survient entre :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. J0 et J7 de vie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. J7 et J14 de vie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. J14 et J21 de vie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. J21 et J28 de vie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A. J0 et J7 de vie\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'infection néonatale bactérienne est dite précoce entre J0 et J7 de vie et tardive entre J8 et J28.\\n\\nSource : Néonatalogie.pdf, XII.1.1 Définition ; L'essentiel en pédiatrie tropicale – PédiatrieA-1 (Le nouveau-né), p. 78\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"KL, 6 mois, sexe masculin, fièvre à 40 °C. Il tolère sa fièvre s'il a :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"a. un temps de recoloration cutané inférieur à 3 secondes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"b. des extrémités froides\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"c. un teint grisâtre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"d. un geignement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. a. un temps de recoloration cutané inférieur à 3 secondes\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Signes de bonne tolérance de la fièvre : faciès vultueux, cri vigoureux, téguments chauds, TRC immédiat < 3 secondes, conscience normale. Extrémités froides, teint grisâtre, geignement (cri plaintif) et TRC > 3 s sont des signes de mauvaise tolérance.\\n\\nSource : Pédiatrie Licence 2 (diaporamas Prof Assé), Fièvre de l'enfant – apprécier sa tolérance ; L'essentiel en pédiatrie tropicale – PédiatrieA-2 (Problèmes fréquents), Fièvre\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'enfant né à terme eutrophique, allaité et correctement nourri, quadruple son poids de naissance à :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 24 mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 9 mois\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 12 mois\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 3 mois\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A. 24 mois\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le poids de naissance est doublé à 3 mois (au sein), triplé à 12 mois et multiplié par 4 à l'âge de 2 ans (24 mois). Remarque : Pediatrie.pdf indique « quadruplé à 3 ans » ; le cours de Santé infantile L1 donne 2 ans, comme la correction nationale.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Repères de gain de poids et tableau récapitulatif\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'âge recommandé par l'OMS pour débuter le sevrage du nourrisson est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 24 mois ou 1 [libellé tronqué dans le sujet]\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 18 mois\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 16 mois\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 6 mois\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D. 6 mois\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Selon l'OMS : allaitement exclusif de 0 à 6 mois, puis début de l'alimentation de complément dès 6 mois (sein + compléments), le sevrage définitif ayant lieu vers 24 mois. Le sevrage commence donc à 6 mois. Remarque : Le cours parle de « sevrage définitif » à 24 mois ; ici, « débuter le sevrage » désigne l'introduction des compléments à 6 mois. L'option A est mal libellée dans le sujet (« 24 mois ou 1 »).\\n\\nSource : Pédiatrie cours / Cours de pédiatrie 2, Allaitement – modalités de l'alimentation (OMS) ; Livret de tableaux PCIMNE 0-5 ans (2021), p. 31\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'enfant à terme, eutrophique, nourri au sein exclusivement a comme acquisition à l'âge de 3 mois :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. réflexes archaïques présents\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. dirige son regard dans les deux directions\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. a peur de l'étranger\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. s'assoit seul\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. dirige son regard dans les deux directions\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"À 3 mois : tient la tête dans l'axe, disparition des réflexes archaïques, tient un objet placé dans la main, émet des sons, sourire-réponse ; il suit du regard. La peur de l'étranger apparaît vers 9 mois et la position assise plus tard ; les réflexes archaïques ne sont plus présents à 3 mois. Remarque : « Dirige son regard dans les deux directions » n'est pas écrit tel quel dans les cours.\\n\\nSource : Pédiatrie cours / Cours de pédiatrie 2, Étapes du DPM ; L'essentiel en pédiatrie tropicale – PédiatrieA-3 (Raisonnement clinique, annexes), Annexes, tableau II\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'objectif visé par le pédiatre lorsque la gestante réalise l'échographie du premier trimestre est de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Estimer le risque d'hypoglycémie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Rechercher une malformation du fœtus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Vérifier la présence d'une activité cardiaque\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Rechercher un retard de croissance intra-utérin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. Vérifier la présence d'une activité cardiaque\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'échographie du 1er trimestre fait partie du bilan prénatal recommandé (échographies des 1er, 2e et 3e trimestres). Au 1er trimestre, elle vérifie d'abord que la grossesse est évolutive (activité cardiaque) (explication hors cours du projet). La recherche des malformations et du RCIU se fait surtout aux 2e et 3e trimestres.\\n\\nSource : Pédiatrie Licence 2 (diaporamas Prof Assé), Bilan prénatal (cas Watchelôh)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La fièvre élevée désigne l'élévation de la température corporelle prise par voie rectale, le matin à distance des repas, comprise entre :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 37,5-38,5 °C\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 38,5-40 °C\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 40-41 °C\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 36,5-37,5 °C\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. 38,5-40 °C\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Selon le degré thermique : fièvre modérée 37,5-38,5 °C, fièvre élevée 38,5-40 °C, hyperthermie > 40 °C. 36,5-37,5 °C correspond à la normale.\\n\\nSource : Pédiatrie Licence 2 (diaporamas Prof Assé), Fièvre de l'enfant – classification\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cochez parmi les signes paracliniques suivants celui qui est un critère de gravité du paludisme grave :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Hypocalcémie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Hypoglycémie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Thrombopénie sévère\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Hyperleucocytose\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. Hypoglycémie\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les critères biologiques de gravité du paludisme sont : hypoglycémie (≤ 2,2 mmol/l), acidose métabolique, anémie sévère (Hb ≤ 5 g/dl), hyperlactatémie, hyperparasitémie, insuffisance rénale. L'hypocalcémie, la thrombopénie et l'hyperleucocytose ne figurent pas dans cette liste.\\n\\nSource : Pédiatrie Licence 2 (diaporamas Prof Assé), Paludisme grave – critères biologiques\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La diarrhée aiguë du nourrisson est définie par l'émission par 24 heures, depuis moins de 14 jours, d'au moins :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 2 selles molles et liquides\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 3 selles molles et liquides\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 4 selles molles et liquides\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 5 selles molles et liquides\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. 3 selles molles et liquides\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La diarrhée aiguë est l'émission d'au moins trois selles molles ou liquides par 24 heures, évoluant depuis moins de 14 jours.\\n\\nSource : Pédiatrie cours / Cours de pédiatrie 2, Diarrhée aiguë – définition ; Les 12 pratiques familiales (PFE), PFE 9\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les selles de la diarrhée aiguë provoquée par Shigella sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. pâteuses sans glaires ni sang\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. liquides avec des selles\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. liquides sans selles\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. pâteuses avec des glaires et du sang\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D. pâteuses avec des glaires et du sang\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Les shigelles agissent par mécanisme invasif (atteinte de la muqueuse) et donnent une dysenterie : selles glaireuses et sanglantes. Remarque : Le cours parle de selles glaireuses et sanglantes sans préciser « pâteuses » ; les options B et C sont mal libellées dans le sujet.\\n\\nSource : L'essentiel en pédiatrie tropicale – PédiatrieA-2 (Problèmes fréquents), Diarrhée aiguë – pathogénie et définitions\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le principal germe de la diarrhée aiguë virale du nourrisson est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Coronavirus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Entérovirus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Rhinovirus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Rotavirus\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D. Rotavirus\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le rotavirus est le principal agent des diarrhées virales du nourrisson ; c'est pourquoi le vaccin anti-rotavirus figure au calendrier vaccinal (Rota 1 et Rota 2) (explication en partie hors cours du projet). Coronavirus et rhinovirus sont surtout des virus respiratoires.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans (2021), p. 17 (calendrier vaccinal : diarrhées à rotavirus)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les avantages des soins mère-kangourou listés ci-après se trouve un intrus. Cochez l'intrus :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Favorise la prise de poids du nouveau-né\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Favorise l'équilibre thermique du nouveau-né\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Augmente la charge de travail du personnel\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Renforce la confiance de la mère\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. Augmente la charge de travail du personnel\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les soins mère kangourou gardent le nouveau-né au chaud, aident à la mise en route et au maintien de l'allaitement, favorisent le lien mère-enfant et la confiance de la mère, et la prise de poids. Ils ne sont pas présentés comme une charge de travail supplémentaire ; au contraire, la mère devient le principal dispensateur de soins.\\n\\nSource : Néonatalogie.pdf, chap. XVII Soins mère kangourou\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les paramètres suivants sont les composants de la méthode de soins mère-kangourou sauf un. Cochez l'intrus :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Aider bébé à respirer\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Allaitement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Suivi\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Contact peau à peau\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A. Aider bébé à respirer\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La méthode kangourou consiste à porter l'enfant en contact peau à peau et à le nourrir exclusivement au sein, avec un suivi jusqu'à au moins 2500 g. « Aider bébé à respirer » relève de la réanimation néonatale, pas de la méthode kangourou.\\n\\nSource : Néonatalogie.pdf, chap. XVII Soins mère kangourou\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le débit d'oxygène du nouveau-né normal hospitalisé pour détresse respiratoire est compris entre :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 1 et 2 L/min\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 1 et 3 L/min\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 0,5 et 1 L/min\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 1 et 1,5 L/min\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 0,5 et 1 L/min\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Devant un nouveau-né en détresse respiratoire avec saturation < 90 %, on donne de l'oxygène à 0,5-1 l/min (0,5 l/min pour le prématuré, 1 l/min pour le nouveau-né à terme).\\n\\nSource : Néonatalogie.pdf, Réanimation (oxygénothérapie) et V.6 Causes cardiovasculaires\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le principal germe responsable de la bronchiolite aiguë du nourrisson est le :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Virus respiratoire syncytial\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Rhinovirus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Coronavirus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Paramyxovirus\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A. Virus respiratoire syncytial\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Pour la bronchiolite, le germe à craindre est le virus respiratoire syncytial (VRS).\\n\\nSource : Pédiatrie Licence 2 (diaporamas Prof Assé), IRA basses – bronchiolite\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la maladie hémorragique du nouveau-né :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. La race blanche est un facteur favorisant\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. L'allaitement est un facteur favorisant\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. L'accouchement facile est un facteur favorisant\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Le lait artificiel est un facteur favorisant\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. L'allaitement est un facteur favorisant\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Facteurs favorisants de la maladie hémorragique : race noire, prématurité, J2-J3 de vie, absence de vitamine K1 à la naissance, accouchement dystocique, allaitement exclusif (lait maternel pauvre en vitamine K), prise d'anti-vitamine K pendant la grossesse. La race blanche et l'accouchement facile ne sont pas cités ; le lait artificiel est enrichi en vitamines.\\n\\nSource : Pédiatrie Licence 2 (diaporamas Prof Assé), Maladie hémorragique du nouveau-né ; L'essentiel en pédiatrie tropicale – PédiatrieA-1 (Le nouveau-né), p. 96\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__28\",\n       \"num\": \"29\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une femme rhésus positif accouchant d'un enfant rhésus négatif reçoit du sérum anti-D en intramusculaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le sérum anti-D est donné à la mère rhésus négatif qui accouche d'un enfant rhésus positif (dans les 72 h). Une mère rhésus positif n'en reçoit pas : l'énoncé est faux.\\n\\nSource : Pédiatrie cours / Cours de pédiatrie 2, Soins du nouveau-né normal ; Néonatalogie.pdf, XV.5.1 Traitement préventif\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__29\",\n       \"num\": \"30\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson de 3 mois est capable de tenir sa tête dans l'axe.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"À 3 mois, le nourrisson tient la tête droite dans l'axe.\\n\\nSource : Pediatrie.pdf (cours 1re année commune), Développement psychomoteur – la tête ; Pédiatrie cours / Cours de pédiatrie 2, Étapes du DPM\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__30\",\n       \"num\": \"31\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"À 9 mois, le nourrisson est capable de faire bravo et au revoir.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"À 9 mois : marche à 4 pattes, pince pouce-index, « da-da-da, ba-ba-ba », peur de l'étranger, fait bravo et au revoir.\\n\\nSource : Pédiatrie cours / Cours de pédiatrie 2, Étapes du DPM\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__31\",\n       \"num\": \"32\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'échographie du premier trimestre permet de savoir si le fœtus sera trisomique ou pas.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai » : l'échographie du 1er trimestre (mesure de la clarté nucale) sert au dépistage de la trisomie 21 (explication hors cours du projet). Remarque : L'échographie dépiste un risque ; seul un examen du caryotype confirme la trisomie (connaissance générale).\\n\\nSource : Aucune source du projet ne traite ce point\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__32\",\n       \"num\": \"33\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nouveau-né macrosome de sexe masculin a un poids en dessous de 4000 g.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le nouveau-né normal pèse entre 2500 et 4000 g ; le macrosome a un poids supérieur à 4000 g (ex. nouveau-né de mère diabétique > 4000 g). L'énoncé « en dessous de 4000 g » est faux.\\n\\nSource : L'essentiel en pédiatrie tropicale – PédiatrieA-1 (Le nouveau-né), Nouveau-né normal et nouveau-né de mère diabétique\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__33\",\n       \"num\": \"34\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La principale complication respiratoire du prématuré est la maladie des membranes hyalines.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La maladie des membranes hyalines est due à l'immaturité pulmonaire (défaut de surfactant) ; elle est la complication respiratoire du prématuré (« maladie du prématuré essentiellement »).\\n\\nSource : Néonatalogie.pdf, VIII.4.1.3 Complications respiratoires et V.5.1\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__34\",\n       \"num\": \"35\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le prématuré avec signes de danger est pris en charge en unité de néonatologie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le prématuré qui présente des signes de danger ne peut pas être suivi en ambulatoire ni en soins kangourou (critère : absence de signes de danger) ; il est pris en charge en unité de néonatologie.\\n\\nSource : Néonatalogie.pdf, VIII.3 Prise en charge de la prématurité, XVII.5 critères SMK\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__35\",\n       \"num\": \"36\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les nouveau-nés à terme eutrophiques présentent dans 30 à 40 % des cas un ictère en période néonatale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'ictère touche 30 à 40 % des nouveau-nés à terme et 100 % des prématurés.\\n\\nSource : Pédiatrie Licence 2 (diaporamas Prof Assé), Ictère du nouveau-né – fréquence\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__36\",\n       \"num\": \"37\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour traiter le paludisme grave, je prescris 9 doses de 2,4 mg/kg d'artésunate injectable en intraveineuse directe.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Artésunate injectable IV : 2,4 mg/kg à H0, H12, H24 puis toutes les 24 heures, pour un maximum de 9 doses (7 jours de traitement).\\n\\nSource : L'essentiel en pédiatrie tropicale – PédiatrieA-3 (Raisonnement clinique, annexes), Annexes – antipaludiques ; Pédiatrie Licence 2 (diaporamas Prof Assé), Paludisme grave\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__37\",\n       \"num\": \"38\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le principal germe de l'infection materno-fœtale est le streptocoque B.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les germes de l'infection materno-fœtale sont, dans 80 % des cas, le streptocoque B, Escherichia coli et Listeria monocytogenes ; le streptocoque B vient en tête.\\n\\nSource : Néonatalogie.pdf, XII.1.3 Germes ; L'essentiel en pédiatrie tropicale – PédiatrieA-1 (Le nouveau-né), p. 78\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__38\",\n       \"num\": \"39\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson de 9 mois manifeste de la peur devant un visage non familier.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La peur de l'étranger apparaît vers 9 mois.\\n\\nSource : Pédiatrie cours / Cours de pédiatrie 2, Étapes du DPM (9 mois)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__39\",\n       \"num\": \"40\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La déshydratation est une complication fréquente du marasme sévère.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Faux ».\\n\\nSource : L'essentiel en pédiatrie tropicale – PédiatrieA-2 (Problèmes fréquents), Malnutrition – problèmes, p. 117 ; Pédiatrie Licence 2 (diaporamas Prof Assé), Malnutrition – problèmes\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__40\",\n       \"num\": \"41\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'association ceftriaxone + aminoside est l'antibiotique probabiliste de première intention pour traiter l'infection bactérienne néonatale précoce.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans l'infection précoce, les principaux germes (streptocoque B, E. coli) sont sensibles à l'amoxicilline/ampicilline : l'association de 1re intention est ampicilline (ou amoxicilline) + aminoside. Le recours aux C3G (ceftriaxone, céfotaxime) concerne surtout l'infection tardive à germes résistants.\\n\\nSource : L'essentiel en pédiatrie tropicale – PédiatrieA-1 (Le nouveau-né), Infection bactérienne du nouveau-né, p. 78-79 ; Livret de tableaux PCIMNE 0-5 ans (2021), p. 52\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__41\",\n       \"num\": \"42\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'infection bactérienne néonatale précoce est favorisée par les gestes septiques de l'agent de santé lors de l'accouchement.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le défaut d'hygiène est un facteur favorisant de l'infection du nouveau-né, et l'infection précoce se contracte pendant la grossesse ou l'accouchement (voie basse) ; des gestes septiques lors de l'accouchement la favorisent. D'où l'asepsie rigoureuse recommandée.\\n\\nSource : L'essentiel en pédiatrie tropicale – PédiatrieA-1 (Le nouveau-né), Facteurs favorisants et mode de contamination, p. 79 ; Pediatrie.pdf (cours 1re année commune), Adaptation des moyens de défense\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__42\",\n       \"num\": \"43\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour reconnaître le paludisme simple au centre de santé urbain, je réalise au lit du client une goutte épaisse et un frottis sanguin.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Au lit du malade, on réalise le test de diagnostic rapide (TDR) ; la goutte épaisse et le frottis sanguin se font au laboratoire.\\n\\nSource : Pédiatrie Licence 2 (diaporamas Prof Assé), Paludisme – collaborer à la réalisation du bilan\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__43\",\n       \"num\": \"44\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nouveau-né normal a un temps de recoloration cutanée de 5 secondes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Chez le nouveau-né normal, le temps de recoloration cutanée est inférieur à 3 secondes ; un TRC de 5 s est pathologique.\\n\\nSource : Néonatalogie.pdf, IV.3.5 Constantes normales\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__44\",\n       \"num\": \"45\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson présentant une déshydratation modérée est capable de boire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Signes évidents (modérés) de déshydratation : agité, yeux enfoncés, assoiffé, boit avec avidité. L'incapacité de boire est un signe de déshydratation sévère.\\n\\nSource : L'essentiel en pédiatrie tropicale – PédiatrieA-2 (Problèmes fréquents), Diarrhée – tableau I ; Pédiatrie cours / Cours de pédiatrie 2, tableau des signes de déshydratation\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__45\",\n       \"num\": \"46\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nouveau-né normal a une coloration rouge brun.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La coloration normale du nouveau-né est rose (parfois discrète cyanose des extrémités) ; la peau prend progressivement « la couleur locale » au cours de la 1re semaine.\\n\\nSource : Néonatalogie.pdf, IV.3.6 Peau et muqueuses ; L'essentiel en pédiatrie tropicale – PédiatrieA-1 (Le nouveau-né), Nouveau-né normal\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__46\",\n       \"num\": \"47\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'urée et la créatinine du sang font partie du bilan prénatal recommandé.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Bilan prénatal recommandé : glycémie, hémogramme, groupe ABO/rhésus, électrophorèse de l'hémoglobine, sérologies toxoplasmose, rubéole, syphilis, VIH, et échographies des 3 trimestres. L'urée et la créatinine n'y figurent pas.\\n\\nSource : Pédiatrie Licence 2 (diaporamas Prof Assé), Bilan prénatal ; Pédiatrie cours / Cours de pédiatrie 2, Bilan prénatal\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__47\",\n       \"num\": \"48\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson de 2 mois allaité au sein émettant 3 à 4 selles molles par 24 heures est atteint de diarrhée.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai » : 3 selles molles ou plus par 24 heures répondent à la définition de la diarrhée.\\n\\nSource : Pédiatrie cours / Cours de pédiatrie 2, Diarrhée aiguë ; Les 12 pratiques familiales (PFE), PFE 9 ; L'essentiel en pédiatrie tropicale – PédiatrieA-2 (Problèmes fréquents), Diagnostic différentiel, p. 210\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__48\",\n       \"num\": \"49\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le plan A de traitement de la diarrhée est indiqué pour la diarrhée sans signes de déshydratation.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Plan A : diarrhée sans signes de déshydratation, traitée à domicile (liquides, zinc, alimentation, quand revenir).\\n\\nSource : Pediatrie.pdf (cours 1re année commune), Diarrhée – Plan A ; Livret de tableaux PCIMNE 0-5 ans (2021), p. 24\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__49\",\n       \"num\": \"50\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lors de la diarrhée aiguë, le nourrisson de 3 mois reçoit en plus de la réhydratation et de l'alimentation un comprimé de zinc dosé à 20 mg par jour pendant 10 jours.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Zinc comprimé 20 mg : ½ comprimé par jour jusqu'à 6 mois, 1 comprimé au-delà, pendant 10 à 14 jours. À 3 mois, c'est ½ comprimé : l'énoncé est faux. Remarque : Le document PFE indique 14 jours ; le PCIMNE dit 10 à 14 jours.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans (2021), p. 24 (Plan A – donner du zinc)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__50\",\n       \"num\": \"51\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson souffrant d'une diarrhée avec signes évidents de déshydratation est traité pendant les 4 premières heures au centre de santé.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Plan B (signes évidents de déshydratation) : la SRO est administrée au centre de santé sur une période de 4 heures, puis l'enfant est réévalué.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans (2021), p. 24 (Plan B)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__51\",\n       \"num\": \"52\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de la diarrhée aiguë, le tube digestif conserve 50 à 70 % de sa capacité d'absorption et de digestion des nutriments.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai » : l'intestin garde une bonne partie de sa capacité d'absorption pendant la diarrhée, d'où la règle de continuer l'alimentation (explication en partie hors cours du projet). Remarque : Le chiffre de 50 à 70 % n'est pas dans les cours du projet.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans (2021), p. 24 (Plan A – continuer l'alimentation) ; L'essentiel en pédiatrie tropicale – PédiatrieA-2 (Problèmes fréquents), Alimentation\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__52\",\n       \"num\": \"53\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nouveau-né prématuré âgé de 36 semaines d'aménorrhée stable est pris en charge au centre de santé rural.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Un prématuré de 36 SA sans signes de danger peut être suivi au premier niveau (centre de santé), avec la méthode kangourou ; ce sont les signes de danger ou un petit poids (< 2000 g) qui imposent la référence (explication en partie hors cours du projet).\\n\\nSource : Néonatalogie.pdf, XVII.5 critères SMK et référence\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j6-idesfm__53\",\n       \"num\": \"54\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour confirmer le diagnostic de l'avitaminose K1 chez le nouveau-né qui saigne, je collabore avec le médecin pour réaliser un groupe sanguin ABO/Rhésus.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'examen clé pour confirmer le déficit en vitamine K est le temps de Quick (TP-TCK), allongé. Le groupe sanguin ABO/rhésus fait partie du bilan mais ne confirme pas le diagnostic.\\n\\nSource : Pédiatrie Licence 2 (diaporamas Prof Assé), Maladie hémorragique – bilan ; L'essentiel en pédiatrie tropicale – PédiatrieA-1 (Le nouveau-né), p. 98\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J6 (IDE/SFM)\",\n       \"sourceFile\": \"J6_Pediatrie_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
